body { background: var(--paper); font-family: var(--font-text); font-size: 1.0625rem; }
.runhead { display: flex; justify-content: space-between; gap: var(--space-2); padding: var(--space-1) var(--space-4); border-bottom: 1px solid var(--rule-strong); background: var(--sheet); font-family: var(--font-body); font-size: 0.875rem; color: var(--ink-2); }
.runhead span:first-child { font-weight: 700; color: var(--ink); letter-spacing: 0.02em; }
.page { display: grid; grid-template-columns: 13rem minmax(0px, 1fr); gap: var(--space-4); max-width: 80rem; margin: var(--space-4) auto; padding: 0 var(--space-4); }
.toc { position: sticky; top: var(--space-3); align-self: start; font-family: var(--font-body); }
.toc-h { font-weight: 700; padding-bottom: var(--space-1); border-bottom: 2px solid var(--ink); }
.toc a { display: flex; align-items: center; min-height: 44px; text-decoration: none; border-bottom: 1px solid var(--rule); }
.toc a:hover { color: var(--accent-deep); }
main { background: var(--sheet); border: 1px solid var(--rule); padding: var(--space-4) var(--space-5); min-width: 0px; }
:where(h1, h2, h3, h4) { font-family: var(--font-display); font-weight: 600; }
h1 { font-size: var(--t-3xl); line-height: 1.05; letter-spacing: -0.01em; }
.deck { margin-top: var(--space-1); font-style: italic; font-size: var(--t-md); color: var(--ink-2); }
.scenario { margin-top: var(--space-2); padding: var(--space-1) var(--space-2); border: 1px solid var(--rule-strong); font-family: var(--font-body); font-size: 0.9375rem; background: var(--sheet-2); }
.summary { margin-top: var(--space-2); padding-top: var(--space-2); border-top: 1px solid var(--ink); max-width: 70ch; }
section { margin-top: var(--space-5); }
h2 { font-size: var(--t-2xl); padding-bottom: var(--space-1); border-bottom: 2px solid var(--ink); display: flex; gap: var(--space-2); align-items: baseline; }
.rn { font-style: italic; color: var(--ink-3); font-weight: 400; min-width: 2.2rem; }
.intro { margin-top: var(--space-2); color: var(--ink-2); }
.num { font-family: var(--font-body); font-variant-numeric: tabular-nums lining-nums; }
.cols { columns: 20rem 2; column-gap: var(--space-4); column-rule: 1px solid var(--rule); margin-top: var(--space-2); }
.ent { break-inside: avoid; padding: var(--space-1) 0; border-bottom: 1px solid var(--rule); font-family: var(--font-body); font-size: 0.9375rem; }
.ent .sid { color: var(--ink-2); margin-right: 0.3em; }
.ent .sub { display: block; margin-top: 0.15rem; color: var(--ink-2); font-size: 0.875rem; }
.ent .verdict { float: right; margin-left: var(--space-1); }
.lead { display: none; }
.fl { padding: 0px 0.4em; border: 1px solid var(--ink-2); font-size: 0.75rem; color: var(--ink-2); white-space: nowrap; }
.box { margin-top: var(--space-3); padding: var(--space-2) var(--space-3); border: 2px solid var(--mark-contra); background: var(--wash-contra); display: grid; gap: var(--space-1); }
.box-k { font-family: var(--font-body); font-weight: 700; font-size: 0.8125rem; color: var(--mark-contra); }
.box h3 { font-size: var(--t-lg); display: flex; gap: var(--space-1); align-items: center; flex-wrap: wrap; }
.box blockquote { margin: 0px; padding: var(--space-1) 0; border-top: 1px solid var(--mark-contra); border-bottom: 1px solid var(--mark-contra); font-style: italic; max-width: 66ch; }
.mlines { margin-top: var(--space-3); display: grid; gap: var(--space-3); }
.mline h3 { font-size: var(--t-lg); font-style: italic; font-weight: 500; padding-bottom: 0.25rem; border-bottom: 1px solid var(--ink); }
.cnt { font-style: normal; color: var(--ink-3); font-size: 0.875rem; margin-left: 0.4em; }
.mlist { columns: 22rem 2; column-gap: var(--space-4); column-rule: 1px solid var(--rule); margin-top: var(--space-1); }
.mono { break-inside: avoid; padding: var(--space-1) 0; border-bottom: 1px dotted var(--rule-strong); }
.mono h4 { font-size: var(--t-base); font-family: var(--font-body); font-weight: 700; display: flex; gap: var(--space-1); flex-wrap: wrap; align-items: baseline; }
.vr { margin-left: auto; font-weight: 400; }
.mono dl { font-family: var(--font-body); font-size: 0.875rem; margin-top: 0.15rem; }
.mono dt { font-weight: 700; font-size: 0.8125rem; color: var(--ink-2); margin-top: 0.25rem; }
.mono dd { margin: 0px; color: var(--ink); }
.none { color: var(--ink-3); font-family: var(--font-body); font-size: 0.875rem; }
.placed-user { color: var(--accent-deep); font-family: var(--font-body); }
.place { margin-top: var(--space-3); font-family: var(--font-body); }
.xcheck { margin-top: var(--space-2); color: var(--ink-2); }
.mon { margin-top: var(--space-3); padding-top: var(--space-2); border-top: 1px solid var(--ink); }
.mon h3 { font-size: var(--t-lg); display: flex; gap: var(--space-2); flex-wrap: wrap; align-items: center; }
.mon p { margin-top: 0.25rem; }
.trip { display: grid; grid-template-columns: 11rem minmax(0px, 1fr) minmax(0px, 1fr); gap: var(--space-3); margin-top: var(--space-2); align-items: start; }
.cells { border-collapse: collapse; font-family: var(--font-body); font-size: 0.9375rem; width: 100%; }
.cells th, .cells td { border: 1px solid var(--rule-strong); padding: 0.4rem var(--space-1); text-align: left; }
.cells thead th, .cells thead td { background: var(--sheet-2); font-size: 0.8125rem; }
.nn { display: block; font-size: 0.8125rem; color: var(--ink-2); }
.also { margin-top: var(--space-2); display: grid; gap: var(--space-1); font-family: var(--font-body); }
.also li { display: flex; gap: var(--space-2); flex-wrap: wrap; align-items: center; }
.sh { margin-top: var(--space-4); font-size: var(--t-lg); }
.tw { overflow-x: auto; margin-top: var(--space-1); }
.sched { width: 100%; border-collapse: collapse; font-family: var(--font-body); font-size: 0.9375rem; }
.sched th, .sched td { text-align: left; padding: 0.4rem var(--space-2); border-bottom: 1px solid var(--rule); }
.sched thead th { border-bottom: 2px solid var(--ink); font-size: 0.8125rem; }
footer { margin-top: var(--space-5); padding-top: var(--space-2); border-top: 2px solid var(--ink); display: grid; gap: var(--space-2); color: var(--ink-2); font-size: 0.9375rem; }
footer h2 { font-size: var(--t-lg); border: 0px; color: var(--ink); }
.rules-l { columns: 20rem 2; column-gap: var(--space-4); font-family: var(--font-body); }
.rules-l li { break-inside: avoid; display: flex; gap: var(--space-1); flex-wrap: wrap; align-items: center; padding: 0.25rem 0px; border-top: 1px solid var(--rule); }
.baci text { font-family: var(--font-body); }
@media (max-width: 64rem) { .page { grid-template-columns: minmax(0px, 1fr); padding: 0 var(--space-2); } .toc { position: static; } .toc ol { display: flex; flex-wrap: wrap; gap: var(--space-2); } .trip { grid-template-columns: minmax(0px, 1fr); } }
@media (max-width: 48rem) { .runhead { padding: var(--space-1) var(--space-2); flex-wrap: wrap; } main { padding: var(--space-3) var(--space-2); } h1 { font-size: var(--t-2xl); } .cols, .mlist, .rules-l { columns: 1; } }
